        /// </remarks>
        /// <exception cref="ApiException">Thrown when fails to make API call</exception>
        /// <param name="timeout">The amount of time you want TorBox to search for the torrent on the Bittorrent network. If the number of seeders is low or even zero, this value may be helpful to move up. Default is 10. Optional. (optional, default to 10)</param>
        /// <param name="hash">A torrent hash for requesting information about the torrent. Optional. (optional)</param>
        /// <param name="magnet">A magnet link for requesting information abouit the torrent. Optional. (optional)</param>
        /// <param name="file">A torrent file for requesting information about the torrent. Optional. (optional)</param>
        /// <param name="useCacheLookup">If you want to use a pre-cached request if sent before. This can save a lot of time. Default false. (optional, default to false)</param>
        /// <param name="peersOnly">Uses a quick lookup method using the trackers contained within the magnet or file. Requires the submitted magnet or torrent file to contain trackers of UDP or HTTP(S) to work. This will not get metadata such as name, size, or files. Best used for simply and quickly gathering the current seeds and peers according to the trackers. Uses the highest number of all the trackers as the final value. Default off. (optional, default to false)</param>
