        /// <summary>
        /// Request Download Link
        /// </summary>
        /// <remarks>
        /// ### Overview  Requests the download link from the server. Because downloads are metered, TorBox cannot afford to allow free access to the links directly. This endpoint opens the link for 3 hours for downloads. Once a download is started, the user has nearly unlilimited time to download the file. The 1 hour time limit is simply for starting downloads. This prevents long term link sharing.  ### Permalinks  Instead of generating many CDN urls by requesting this endpoint, you can instead create a permalink such as: &#x60;https://api.torbox.app/v1/api/torrents/requestdl?token&#x3D;APIKEY&amp;torrent_id&#x3D;NUMBER&amp;file_id&#x3D;NUMBER&amp;redirect&#x3D;true&#x60; and when a user clicks on it, it will automatically redirect them to the CDN link. This saves requests and doesn&#39;t abuse the API. Use this method rather than saving CDN links as they are not permanent. To invalidate these permalinks, simply reset your API token or delete the item from your dashboard.  ### Authorization  Requires an API key as a parameter for the &#x60;token&#x60; parameter. 
        /// </remarks>
        /// <exception cref="ApiException">Thrown when fails to make API call</exception>
        /// <param name="token">Your API Key</param>
        /// <param name="torrentId">The torrent&#39;s ID that you want to download</param>
        /// <param name="fileId">The files&#39;s ID that you want to download (optional, default to 0)</param>
        /// <param name="zipLink">If you want a zip link. Required if no file_id. Takes precedence over file_id if both are given. (optional, default to false)</param>
        /// <param name="userIp">The user&#39;s IP to determine the closest CDN. Optional. (optional)</param>
        /// <param name="redirect">If you want to redirect the user to the CDN link. This is useful for creating permalinks so that you can just make this request URL the link. (optional, default to false)</param>
        /// <param name="appendName">If you want to add the \&quot;filename\&quot; parameter to the returned CDN link. Optional. Default false. (optional, default to false)</param>
        /// <param name="cancellationToken">Cancellation Token to cancel the request.</param>
        /// <returns><see cref="Task"/>&lt;<see cref="IRequestTorrentDownloadLinkApiResponse"/>&gt;</returns>
        Task<IRequestTorrentDownloadLinkApiResponse> RequestTorrentDownloadLinkAsync(string token, long torrentId, Option<long> fileId = default, Option<bool> zipLink = default, Option<string> userIp = default, Option<bool> redirect = default, Option<bool> appendName = default, System.Threading.CancellationToken cancellationToken = default);

